∀ {n : ℕ} (first j i : Fin n),
  FTC.Counterexample.clusterMembers first i =
    {z | FTC.Counterexample.assignedCenter first j z = FTC.Counterexample.assignedCenter first j i}

∀ {I : Type u_1} {X : Type u_2} [inst : Fintype X] [inst_1 : MetricSpace X] {k : ℕ} {U : Finset I}
  {entries : I → FTC.Entry X} {p : I} {ρ : ℝ} (oracle : FTC.FiniteMetric.IndexedConstrainedOracle U entries p ρ)
  (x : X), FTC.FiniteMetric.weightedTrialScore oracle x ≤ FTC.FiniteMetric.weightedEstimate oracle

∀ {I : Type u_1} {X : Type u_2} [DecidableEq I] [Fintype X] [DecidableEq X] [inst : MetricSpace X] {k : ℕ}
  {U : Finset I} {entries : I → FTC.Entry X} {p : I} {ρ : ℝ}
  (oracle : FTC.FiniteMetric.IndexedConstrainedOracle U entries p ρ) (x : X),
  0 ≤ FTC.FiniteMetric.weightedTrialScore oracle x

∀ {I : Type u_1} {S : Type u_2} [inst : DecidableEq I] {c : I → S → ℝ} {α : ℝ}
  (oracle : FTC.ApproxSensitivityOracle c α),
  (∀ (i : I) (s : S), 0 ≤ c i s) → 0 < α → ∀ {Q : Finset I} {i : I}, i ∈ Q → 0 ≤ oracle.score Q i

∀ {X : Type u_1} [inst : Fintype X] [inst_1 : DecidableEq X] [inst_2 : MetricSpace X] {k : ℕ} {P : Finset X} {p : X}
  {ρ : ℝ} (oracle : FTC.FiniteMetric.ConstrainedOracle P p ρ),
  p ∈ P → FTC.FiniteMetric.estimate oracle ≤ FTC.sensitivity FTC.FiniteMetric.kmeansLoss P p

∀ {I : Type u_1} {S : Type u_2} [inst : DecidableEq I] {c : I → S → ℝ} {α : ℝ}
  (oracle : FTC.ApproxSensitivityOracle c α),
  0 < α → ∀ {Q : Finset I} {i : I}, i ∈ Q → FTC.sensitivity c Q i / α ≤ oracle.score Q i

∀ {X : Type u_1} [inst : Fintype X] [DecidableEq X] [inst_2 : MetricSpace X] {k : ℕ} {P : Finset X} {p : X} {ρ : ℝ}
  (oracle : FTC.FiniteMetric.ConstrainedOracle P p ρ) (x : X),
  FTC.FiniteMetric.trialScore oracle x ≤ FTC.FiniteMetric.estimate oracle

∀ {I : Type u_1} {X : Type u_2} [DecidableEq I] [inst : Fintype X] [DecidableEq X] [inst_2 : MetricSpace X] {k : ℕ}
  {U : Finset I} {entries : I → FTC.Entry X} {p : I} {ρ : ℝ}
  (oracle : FTC.FiniteMetric.IndexedConstrainedOracle U entries p ρ), 0 ≤ FTC.FiniteMetric.weightedEstimate oracle

∀ {I : Type u_1} {X : Type u_2} [inst : DecidableEq I] [Fintype X] [DecidableEq X] [inst_3 : MetricSpace X] {k : ℕ}
  (entries : I → FTC.Entry X) (U : Finset I) (p : I),
  (entries p).weight = 0 → FTC.sensitivity (FTC.FiniteMetric.weightedLoss entries) U p = 0

∀ {I : Type u_1} {J : Type u_2} {S : Type u_3} [DecidableEq J] {a : J → S → ℝ} {sample : I → J} {score : J → ℝ} {T : ℝ}
  {m : ℕ} {i : I} {s : S},
  (∀ (x : J) (s : S), 0 ≤ a x s) → 0 ≤ T → 0 ≤ score (sample i) → 0 ≤ FTC.sampledContribution a sample score T m i s

∀ {I : Type u_1} {X : Type u_2} [inst : DecidableEq I] [Fintype X] [DecidableEq X] [inst_3 : MetricSpace X] {k : ℕ}
  {U : Finset I} {entries : I → FTC.Entry X} {p : I} {ρ : ℝ}
  (oracle : FTC.FiniteMetric.IndexedConstrainedOracle U entries p ρ),
  p ∈ U →
    ∀ (x : X),
      FTC.FiniteMetric.weightedTrialScore oracle x ≤ FTC.sensitivity (FTC.FiniteMetric.weightedLoss entries) U p

∀ {X : Type u_1} [Fintype X] [inst : DecidableEq X] [inst_1 : MetricSpace X] {k : ℕ} {P : Finset X} {p : X} {ρ : ℝ}
  (oracle : FTC.FiniteMetric.ConstrainedOracle P p ρ),
  p ∈ P → ∀ (x : X), FTC.FiniteMetric.trialScore oracle x ≤ FTC.sensitivity FTC.FiniteMetric.kmeansLoss P p

∀ {I : Type u_1} {X : Type u_2} [DecidableEq I] [Fintype X] [DecidableEq X] [inst : MetricSpace X] {k : ℕ}
  (entries : I → FTC.Entry X) (i : I) (C : FTC.FiniteMetric.CenterSet X k),
  0 ≤ FTC.FiniteMetric.weightedLoss entries i C

∀ {a b : FTC.Hardness.Computation.Ty} {P : FTC.Hardness.Complexity.PromiseProblem a}
  {Q : FTC.Hardness.Complexity.PromiseProblem b},
  FTC.Hardness.Complexity.NPHard P → ∀ (r : FTC.Hardness.Complexity.PolyReduction P Q), FTC.Hardness.Complexity.NPHard Q
